            return message.replace(/"/g, "'");
        },
        remoteBranchExists: function(runCommand, workingDir, branchName) {
            var out = runCommand('git ls-remote --heads origin ' + branchName, workingDir) || '';
            return out.indexOf('refs/heads/' + branchName) !== -1;
        }
    };
}

